### Event Handling
```csharp
// FIXED: Coordinate conversion
private void HandleCanvasEvents(Rect area)
{
    Event evt = Event.current;

    // Convert screen space to canvas space
    Vector2 canvasMousePos = evt.mousePosition - area.position;

    if (evt.type == EventType.MouseDown && area.Contains(evt.mousePosition))
    {
        bool clickedNode = false;
        foreach (var node in _currentGraph.Nodes)
        {
            Rect nodeRect = GetNodeRect(node.Id.Value);
            if (nodeRect.Contains(canvasMousePos))  // ✅ CORRECT SPACE!
            {
                _selectedNodeId = node.Id.Value;
                clickedNode = true;
                evt.Use();
                break;
            }
        }

        if (!clickedNode)
            _selectedNodeId = -1;
    }
}
// ✅ IMPROVEMENTS:
// - Explicit coordinate conversion
// - Clear conversion logic
// - Selection works reliably
// - Easy to understand
```

### Node Rectangle Calculation
```csharp
// FIXED: Consistent canvas-space coordinates
private Rect GetNodeRect(int nodeId)
{
    if (!_nodePositions.TryGetValue(nodeId, out var pos))
    {
        pos = new Vector2(200 + nodeId * 250, 200);
        _nodePositions[nodeId] = pos;
    }

    // Calculate in canvas-local space
    Vector2 canvasPos = (pos + _panOffset) * _zoom;

    return new Rect(canvasPos, new Vector2(NodeWidth, NodeHeight) * _zoom);
}
// ✅ IMPROVEMENTS:
// - Always returns canvas-space coordinates
// - Pan and zoom applied consistently
// - Works with hit testing
// - Matches drawing coordinates
```

