using UnityEngine;
using Sirenix.OdinInspector;
using Extensions.EventBus;

namespace Extensions.Dialogue.Runtime
{
    /// <summary>
    /// Voiceover dialogue engine for auto-playing dialogue in areas.
    /// Supports external graph traversal and smooth dialogue transitions.
    /// Shares common interface with DialogueEngine for consistency.
    /// </summary>
    public sealed class VoiceoverDialogueEngine : MonoBehaviour, IDialogueEngine
    {
        [SerializeField] private DialogueState state = new();
        private Data.DialogueGraph _currentGraph;
        private Data.NodeId _currentNodeId = Data.NodeId.Invalid;
        private IGameServices _gameServices;
        private IDialoguePresenter _presenter;
        private ICommandFactory _commandFactory;
        private DialogueScheduler _scheduler = new();
        private float _elapsedTime;
        private bool _isPlaying;

        IDialogueEngine.EngineState IDialogueEngine.CurrentState => _isPlaying ? IDialogueEngine.EngineState.Playing : IDialogueEngine.EngineState.Idle;
        public Data.NodeId CurrentNode => _currentNodeId;
        public DialogueState State => state;

        public void Initialize(IGameServices gameServices, IDialoguePresenter presenter, ICommandFactory commandFactory)
        {
            _gameServices = gameServices;
            _presenter = presenter;
            _commandFactory = commandFactory;
        }

        void IDialogueEngine.PlayFromNode(Data.DialogueGraph graph, Data.NodeId startNodeId)
        {
            if (graph == null)
            {
                Debug.LogError("[VoiceoverDialogueEngine] Cannot play null graph");
                return;
            }

            if (_isPlaying)
            {
                ((IDialogueEngine)this).StopPlayback();
            }

            _currentGraph = graph;
            _currentNodeId = startNodeId;
            _elapsedTime = 0f;
            _scheduler.Clear();
            _isPlaying = true;

            EventBus<DialogueStartedEvent>.Raise(new DialogueStartedEvent { StartNode = _currentNodeId });
            ProcessCurrentNode();
        }

        void IDialogueEngine.Play(Data.DialogueGraph graph)
        {
            ((IDialogueEngine)this).PlayFromNode(graph, graph.StartNode);
        }

        void IDialogueEngine.AdvanceToNext()
        {
            if (!_isPlaying)
            {
                Debug.LogWarning("[VoiceoverDialogueEngine] Not currently playing");
                return;
            }

            var currentNode = _currentGraph.GetNode(_currentNodeId);
            if (currentNode?.NextNodes.Length > 0)
            {
                var previousNodeId = _currentNodeId;
                _currentNodeId = currentNode.NextNodes[0];

                EventBus<DialogueAdvancedEvent>.Raise(new DialogueAdvancedEvent
                {
                    PreviousNode = previousNodeId,
                    NextNode = _currentNodeId
                });

                ProcessCurrentNode();
            }
            else
            {
                ((IDialogueEngine)this).StopPlayback();
            }
        }

        void IDialogueEngine.JumpToNode(Data.NodeId nodeId)
        {
            if (!_isPlaying)
            {
                Debug.LogWarning("[VoiceoverDialogueEngine] Not currently playing");
                return;
            }

            var previousNodeId = _currentNodeId;
            _currentNodeId = nodeId;

            EventBus<DialogueAdvancedEvent>.Raise(new DialogueAdvancedEvent
            {
                PreviousNode = previousNodeId,
                NextNode = _currentNodeId
            });

            ProcessCurrentNode();
        }

        void IDialogueEngine.Pause()
        {
            if (_isPlaying)
            {
                _presenter.Hide();
            }
        }

        void IDialogueEngine.Resume()
        {
            if (!_isPlaying)
            {
                ProcessCurrentNode();
            }
        }

        void IDialogueEngine.StopPlayback()
        {
            _isPlaying = false;
            _currentNodeId = Data.NodeId.Invalid;
            _scheduler.Clear();
            _presenter.Hide();

            EventBus<DialogueEndedEvent>.Raise(new DialogueEndedEvent { LastNode = _currentNodeId });
        }

        private void ProcessCurrentNode()
        {
            var node = _currentGraph.GetNode(_currentNodeId);
            if (node == null)
            {
                Debug.LogError($"[VoiceoverDialogueEngine] Node {_currentNodeId} not found");
                ((IDialogueEngine)this).StopPlayback();
                return;
            }

            var context = new DialogueContext(state, _gameServices, _commandFactory, _currentNodeId, _elapsedTime);
            node.Process(in context, this, _presenter);
        }

        private void Update()
        {
            if (!_isPlaying)
                return;

            _elapsedTime += Time.deltaTime;

            var context = new DialogueContext(state, _gameServices, _commandFactory, _currentNodeId, _elapsedTime);
            _scheduler.Update(Time.deltaTime, in context);
        }

        private void OnDestroy()
        {
            _presenter?.Hide();
        }
    }

    /// <summary>
    /// Trigger area that starts voiceover dialogue when player enters.
    /// Automatically transitions to next dialogue area smoothly.
    /// </summary>
    public sealed class VoiceoverDialogueTrigger : MonoBehaviour
    {
        [SerializeField] private Data.DialogueGraph dialogueGraph;
        [SerializeField] private Data.NodeId startNode = new(0);
        [SerializeField] private bool autoPlayOnTrigger = true;
        [SerializeField] private string playerTag = "Player";

        private VoiceoverDialogueEngine _engine;
        private bool _hasTriggered;

        private void Start()
        {
            _engine = FindFirstObjectByType<VoiceoverDialogueEngine>();
            if (_engine == null)
            {
                Debug.LogError("[VoiceoverDialogueTrigger] No VoiceoverDialogueEngine found in scene");
            }
        }

        private void OnTriggerEnter(Collider other)
        {
            if (!autoPlayOnTrigger || _hasTriggered || dialogueGraph == null || _engine == null)
                return;

            if (other.CompareTag(playerTag))
            {
                _hasTriggered = true;
                ((IDialogueEngine)_engine).PlayFromNode(dialogueGraph, startNode);
            }
        }

        private void OnTriggerExit(Collider other)
        {
            if (other.CompareTag(playerTag))
            {
                _hasTriggered = false;
            }
        }

        [Button]
        public void TriggerDialogue()
        {
            if (_engine == null) _engine = FindFirstObjectByType<VoiceoverDialogueEngine>();
            if (dialogueGraph == null) return;
            ((IDialogueEngine)_engine).PlayFromNode(dialogueGraph, startNode);
        }
    }
}

# Dialogue System - Complete Usage Guide

## Quick Setup

### 1. Interactive Dialogue (NPC Conversation)

```csharp
// Create NPC
var npc = new GameObject("NPC");
npc.AddComponent<DialogueInteractable>().dialogueGraph = conversationGraph;
npc.AddComponent<SphereCollider>().isTrigger = true;

// Player detects it
player.AddComponent<PlayerInteractor>();

// Result: Player presses E → Dialogue starts
```

### 2. Voiceover Dialogue (Auto-Play Story)

```csharp
// Create voiceover engine
voiceoverEngine.AddComponent<VoiceoverDialogueEngine>();

// Create zone
zone.AddComponent<VoiceoverDialogueTrigger>().dialogueGraph = storyGraph;
zone.AddComponent<SphereCollider>().isTrigger = true;

// Result: Player walks in → Dialogue auto-plays
```

### 3. Setup Dialogue UI

```csharp
// Bottom UI (default)
canvas.AddComponent<Scripts.UI.Dialogue.BottomDialoguePresenter>();

// Combat UI (voiceover)
canvas.AddComponent<Scripts.UI.Dialogue.CombatDialoguePresenter>();

// Manager for switching
uiManager.AddComponent<Scripts.UI.Dialogue.DialogueUIManager>();
```

---

## Creating Dialogue Graphs

### Node Types

**LineNode** - Single line of dialogue
```csharp
new LineNode {
    TextKey = new TextKey(1),      // Text reference
    Speaker = new SpeakerId(1),    // Who's speaking
    Style = new StyleId(0),        // UI style
    Commands = new CommandData[] {}, // Actions to execute
    NextNodes = new[] { new NodeId(1) } // Connections
}
```

**ChoiceNode** - Player choices
```csharp
new ChoiceNode {
    Options = new[] {
        new ChoiceOption {
            TextKey = new TextKey(10),
            NextNode = new NodeId(2)
        },
        new ChoiceOption {
            TextKey = new TextKey(11),
            NextNode = new NodeId(3)
        }
    }
}
```

### Creating Graphs in Code

```csharp
var graph = ScriptableObject.CreateInstance<DialogueGraph>();
graph.GraphName = "MyDialogue";
graph.StartNode = new NodeId(0);
graph.Nodes = new[]
{
    new LineNode { /* ... */ },
    new ChoiceNode { /* ... */ },
    // ...
};
```

### Using Graph Editor

```
Assets > Create > Dialogue > Dialogue Graph
Tools > Dialogue System > Dialogue Graph Editor
```

---

## State Management

Track variables without coupling:

```csharp
// Define keys
StateKey<bool> hasMetNPC = new StateKey<bool>(1);
StateKey<int> reputation = new StateKey<int>(2);
StateKey<float> timeElapsed = new StateKey<float>(3);

// Set in commands
new SetBoolCommand(hasMetNPC, true)
new SetIntCommand(reputation, 50)
new IncrementIntCommand(reputation, 10)

// Check in conditions
if (context.State.Get(hasMetNPC)) { }
```

---

## Executing Game Actions

Commands let dialogue trigger game logic:

### Built-in Commands
- `SetBoolCommand` - Set boolean state
- `SetIntCommand` - Set integer state
- `IncrementIntCommand` - Increment counter
- `DebugLogCommand` - Console output

### Custom Commands

1. Create CommandData:
```csharp
[Serializable]
public sealed class GiveItemCommandData : CommandData
{
    public int ItemId;
    public int Amount = 1;
}
```

2. Create Command:
```csharp
public sealed class GiveItemCommand : IDialogueCommand
{
    private int _itemId, _amount;

    public GiveItemCommand(int itemId, int amount)
    {
        _itemId = itemId;
        _amount = amount;
    }

    public void Execute(in DialogueContext context)
    {
        var services = context.GameServices as GameServices;
        services?.Inventory.AddItem(_itemId, _amount);
    }
}
```

3. Register in DialogueManager:
```csharp
_commandFactory.Register<GiveItemCommandData, GiveItemCommand>(
    data => new GiveItemCommand(data.ItemId, data.Amount)
);
```

---

## Branching with Conditions

Show different dialogue based on game state:

```csharp
public sealed class HasItemCondition : DialogueConditionBase
{
    private int _itemId;
    private int _minCount;

    public override bool Evaluate(DialogueContext context)
    {
        var services = context.GameServices as GameServices;
        return services?.Inventory.GetItemCount(_itemId) >= _minCount;
    }
}
```

Use in nodes to conditionally show lines.

